/bin/bash -lc "mkdir -p src tests && cat > package.json <<'EOF'
{\"name\":\"logomocja\",\"version\":\"1.0.0\",\"type\":\"module\",\"scripts\":{\"test\":\"bun test\",\"build\":\"bun build ./src/app.js --outdir ./dist --minify && cp index.html style.css dist/ && sed -i \\\"s|__BASE_PATH__|"'${BASE_PATH:-/}|g'"\\\" dist/index.html\"}}
EOF
cat > tests/interpreter.test.js <<'EOF'
import { test, expect } from 'bun:test';
import { run } from '../src/interpreter.js';
test('żółw rysuje kwadrat', () => {
 const result = run('powtorz 4 [np 100 pw 90]', '2d');
 expect(result.error).toBeNull();
 expect(result.segments).toHaveLength(4);
 expect(result.segments[0].to).toEqual([0,100,0]);
});
EOF
